"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[27171],{27452:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"CrosshairController","desc":"Owns the hand crosshair: a `Crosshair` ScreenGui (`IgnoreGuiInset`, so the image\\nsits on the exact `ViewportSize / 2` the aim rays use) with one centred image.\\n\\nIt shows while the aim camera is on (`Signals.OnShootingCameraToggled`), no\\nturret is mounted (`Signals.OnTurretMounted`; the TurretGui draws its own) and\\nthe character is alive. The aim owner sets what it shows through\\n`Signals.SetCrosshairSource`:\\n\\n- `Style = \\"Cross\\"`: the cross image, sized so the cone edge sits at\\n  `CrosshairMath.radiusPx(Cone(), FieldOfView, ViewportSize.Y)` (never below the\\n  `MinRadiusScale` floor). The live FOV is read every frame, so the sprint FOV\\n  change keeps the size honest.\\n- `Style = \\"Circle\\"` (GrabHook): the circle image at `CircleScale` of the screen\\n  height times the net-perk multiplier (`Signals.RequestReticleScale`).\\n- No source (throwables, anything else in aim mode): the cross at floor size.\\n\\nOwners clear their own source on unequip / dismount (`CrosshairMath.applySource`:\\na late clear cannot wipe a newer owner\'s source). Leaving aim mode resets the\\nnet-perk multiplier; character removal also clears the source and aim flag. The size eases on one `RenderStepped` bound only while the\\ncrosshair is visible.","realm":["Client"],"source":{"line":27,"path":"src/StarterPlayer/StarterPlayerScripts/CrosshairController.client.luau"}}')}}]);